={{ JSON.stringify({
  contents: [{ parts: [{ text:
    'Instrucción de seguimiento sobre una señal de trading ya confirmada. ' +
    'Señal original: instrumento ' + $json.instrument + ', dirección ' + $json.direction +
    ', entrada ' + $json.entry_price + ', SL ' + $json.sl + ', TP ' + $json.tp + '. ' +
    'Mensaje de seguimiento (reply a esa señal): \'' + $json.raw_text + '\'. ' +
    'Clasificá modification_type entre ENTRY_CHANGE, SL_CHANGE, CANCEL, TP_UPDATE, CLOSE_AT_PRICE. ' +
    'target_price solo si el mensaje trae un precio explícito, si no null. No inventes valores.'
  }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        modification_type: { type: 'STRING', enum: ['ENTRY_CHANGE','SL_CHANGE','CANCEL','TP_UPDATE','CLOSE_AT_PRICE'] },
        target_price: { type: 'NUMBER', nullable: true }
      },
      required: ['modification_type']
    }
  }
}) }}

parameters.jsCode:
// Normaliza la respuesta de Gemini (structured JSON via responseSchema) al
// mismo shape que produce "Expandir targets" para la rama regex, y la
// enchufa al mismo INSERT/EA-action que la rama regex.
//
// Limitacion conocida (a reportar): a diferencia de la rama regex, esta
// rama NO reintenta 1 vez en caso de error de Gemini (seccion 4.4 del
// protocolo) ni marca PENDING_MANUAL si Gemini falla — el nodo HTTP
// simplemente fallaria el workflow. Falta ese manejo de error, ver
// resumen final de la tarea.
//
// Tambien: solo aplica sobre la PRIMERA sub-señal encontrada
// (matched_signals[0]) — no reparte a multiples sub-señales como
// CLOSE_ALL_TO_BE, porque los tipos que llegan por Gemini (ENTRY_CHANGE,
// SL_CHANGE, CANCEL, TP_UPDATE, CLOSE_AT_PRICE) no tienen ese requisito
// en el diseño de la tarea.

const context = $('Enrutar clasificación').item.json;
const raw = $json;

let parsed;
try {
  const text = raw.candidates[0].content.parts[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Fase 4: no se pudo parsear la respuesta estructurada de Gemini: ' + e.message);
}

const target = context.matched_signals[0];

let ea_action = null; // ninguno de los tipos que llegan por Gemini tiene
                       // accion de EA equivalente hoy (ver notas de la tarea).

return [{
  json: {
    signal_id: target.id,
    signal_uid: target.signal_uid,
    mt4_ticket: target.mt4_ticket,
    modification_type: parsed.modification_type,
    target_price: parsed.target_price != null ? Number(parsed.target_price) : null,
    raw_text: context.raw_text,
    message_id: context.message_id,
    interpreted_by: 'AI',
    ea_action,
  },
}];

// Fase 4: arma el JSON de comando sobre posicion abierta, mismo contrato
// que ya usa el dashboard (mt4-bridge/FORMATO_ARCHIVOS.md seccion 4.3):
// mt4-bridge/orders/actions/{ticket}-{action}.json
const ticket = $json.mt4_ticket;
const action = $json.ea_action;

const payload = { ticket, action };
const buffer = Buffer.from(JSON.stringify(payload, null, 2), 'utf-8');
const binary = await this.helpers.prepareBinaryData(buffer, `${ticket}-${action}.json`, 'application/json');

return [{
  json: { ...$json, action_ticket: ticket },
  binary: { data: binary },
}];
